import ctypes
import threading

from abc import ABCMeta, abstractmethod
from builtins import bytes  # comes from `future` package
from copy import deepcopy
from typing import Union
from six import add_metaclass, PY2, PY3

from ..commons import LOGGER, LOCK, RESPONSES_QUEUE
from ..exceptions import MessageSanityCheckError, ByteStreamLengthError
from ..utils import bytearray_, bytes_


__all__ = [
    'u8', 'u16', 'u32', 'i32',
    'MESSAGE_MAX_LENGTH',
    'msg_id_to_msg_class', 'msg_id_to_msg_name',
    'QUERY_MANAGER_STORE'
]


def add_to__all__(obj):
    if obj.__name__ not in __all__:
        __all__.append(obj.__name__)
    return obj


class fields_values_as_hex(object):
    def __init__(self, cond):
        self.cond = cond

    def __call__(self, cls):
        cls._fields_values_as_hex = self.cond
        return cls


u8 = ctypes.c_ubyte     # unsigned char
u16 = ctypes.c_ushort   # short
u32 = ctypes.c_uint     # unsigned int
i32 = ctypes.c_int      # signed int

MAPF_LSB = 2
MESSAGE_MAX_LENGTH = 65536

TRACES_IDS = []

msg_id_to_msg_class = {}
msg_id_to_msg_name = {}


@add_to__all__
def register_message(msg_cls):
    msg_id_to_msg_class[msg_cls.id] = msg_cls
    msg_id_to_msg_name[msg_cls.id] = msg_cls.__name__
    return msg_cls


@add_to__all__
def register_trace_ind(msg_cls):
    TRACES_IDS.append(msg_cls.id)
    return msg_cls


@add_to__all__
def change_endianness(stream, limit=0):
    # type: (Union[bytearray, bytes], int) -> bytearray
    """
    Change ABCD to DCBA byte order in each 4-byte word.
    If `limit` > 0 is provided, only stream[0:limit] part is affected.
    """
    if not stream:
        return bytearray()

    stream_length = len(stream)

    if limit > 0:
        length = min(limit, stream_length)
    else:
        length = stream_length
    if (length % 4 != 0) or not length:
        raise ByteStreamLengthError("Converted stream is not 4-byte aligned, and has length {}".format(length))

    data = stream[:length]

    swapped = bytearray(length)

    swapped[0::4] = bytearray_(data[3::4])
    swapped[1::4] = bytearray_(data[2::4])
    swapped[2::4] = bytearray_(data[1::4])
    swapped[3::4] = bytearray_(data[0::4])
    remainder = bytearray_(stream[length:])

    swapped.extend(remainder)
    return swapped


@add_to__all__
def change_header_endianness(stream):
    # type: (bytearray) -> bytearray
    return change_endianness(stream, limit=16)


@add_to__all__    # noqa: C901
def message_sanity_check(header):  # noqa: C901
    if header.id == 0:
        raise MessageSanityCheckError("id == 0")
    if header.length == 0:
        raise MessageSanityCheckError("length == 0")

    if header.receiver.board == 0:
        raise MessageSanityCheckError("receiver.board == 0")
    if header.receiver.cpu == 0:
        raise MessageSanityCheckError("receiver.cpu == 0")
    if header.receiver.task == 0:
        raise MessageSanityCheckError("receiver.task == 0")

    if header.sender.board != 0:
        raise MessageSanityCheckError("sender.board != 0")
    if header.sender.cpu != 0:
        raise MessageSanityCheckError("sender.cpu != 0")
    if header.sender.task != 0:
        raise MessageSanityCheckError("sender.task != 0")

    if header.flags.system != 0:
        raise MessageSanityCheckError("flags.system != 0")
    if header.flags.user != 0:
        raise MessageSanityCheckError("flags.user != 0")


@add_to__all__
class Structure(ctypes.Structure):

    def __repr__(self):
        res = []
        for field in self._fields_:
            if len(field) == 2:
                name, ctype = field
            if len(field) == 3:
                name, ctype, bits = field

            if (not self._fields_values_as_hex
                    or name == 'length'
                    or 'ctypes.c_' not in str(ctype)):
                item = '{}={}'.format(name, getattr(self, name))
            else:
                item = '{}={}'.format(name, hex(int(getattr(self, name))))

            res.append(item)
        return self.__class__.__name__ + '(' + ','.join(res) + ')'

    def __eq__(self, other):
        fields_equality = self._fields_ == other._fields_
        if not fields_equality:
            return False

        for name, _ in self._fields_:
            value_equality = getattr(self, name) == getattr(other, name)
            if not value_equality:
                return False
        return True

    def from_bytearray(self, byte_stream):
        # type: (bytearray) -> Structure
        """
        Helper function
        """
        fit = min(len(byte_stream), ctypes.sizeof(self))
        ctypes.memmove(ctypes.addressof(self), bytes_(byte_stream), fit)
        return self

    def get_copy(self):
        return deepcopy(self)


@add_to__all__
@fields_values_as_hex(True)
class SMessageAddress(Structure):
    _fields_ = [
        ('task', u16),
        ('cpu', u8),
        ('board', u8)
    ]


@add_to__all__
@fields_values_as_hex(True)
class SHeaderFlags(Structure):
    _fields_ = [
        ('user', u8),
        ('system', u8),
    ]


@add_to__all__
@fields_values_as_hex(True)
class SMessageHeader(Structure):
    _fields_ = [
        ('id', u16),
        ('pad', u16),
        ('receiver', SMessageAddress),
        ('sender', SMessageAddress),
        ('flags', SHeaderFlags),
        ('length', u16)  # the length of the whole message including the header. The unit is bytes.
    ]


@add_to__all__
@fields_values_as_hex(True)
class SBrowserObject(Structure):
    _fields_ = [
        ('objectName', u32),
        ('objectId', u32)
    ]


@add_to__all__
class Message(ctypes.Structure):

    def __init__(self, *args, **kwargs):
        super(Message, self).__init__(*args, **kwargs)
        self.payload_is_little_endian = True

    def _set_change_endianness_method(self, byte_stream):
        self.payload_is_little_endian = self._determine_payload_endianness(byte_stream)

        if not self.payload_is_little_endian:  # and message_header.id != UE_TRACING_REPORT_IND_MSG:
            self._change_endianness = change_endianness
        else:
            self._change_endianness = change_header_endianness

    def deserialize(self, byte_stream):
        # type: (bytearray)-> Message
        byte_stream = bytearray_(byte_stream)
        self._set_change_endianness_method(byte_stream)

        byte_stream = self._change_endianness(byte_stream)
        fit = min(len(byte_stream), ctypes.sizeof(self))
        ctypes.memmove(ctypes.addressof(self), bytes_(byte_stream), fit)
        return self

    @classmethod
    def _determine_payload_endianness(cls, byte_stream):
        header_length = 16

        byte_stream = bytearray_(byte_stream)

        message_header = SMessageHeader.from_buffer_copy(change_endianness(byte_stream[:header_length]))
        payload_is_little_endian = message_header.flags.user & (1 << MAPF_LSB)
        return payload_is_little_endian

    @classmethod
    def from_bytearray(cls, byte_stream):
        # type: (bytearray) -> Message
        """
        Helper function
        """
        fit = min(len(byte_stream), ctypes.sizeof(cls))
        payload_is_little_endian = cls._determine_payload_endianness(byte_stream)
        if not payload_is_little_endian:
            change_endianness_method = change_endianness
        else:
            change_endianness_method = change_header_endianness
        return cls.from_buffer_copy(change_endianness_method(byte_stream[:fit]))


@add_to__all__
class RequestMessage(Message):
    def __init__(self, board, cpu, *args, **kwargs):
        super(RequestMessage, self).__init__(*args, **kwargs)
        self.header.receiver.board = board
        self.header.receiver.cpu = cpu
        self.header.receiver.task = 0x0227
        self.header.id = self.id
        self.header.length = ctypes.sizeof(self)

    def serialize(self):
        # type: () -> bytearray
        if PY2:
            return change_endianness(buffer(self)[:])  # noqa: F821
        if PY3:
            return change_endianness(bytes(memoryview(self)))


@add_to__all__
class ResponseMessage(Message):
    def __init__(self, *args, **kwargs):
        super(ResponseMessage, self).__init__(*args, **kwargs)


class QueryManagerStore(object):
    def __init__(self):
        self._registry = {}

    def register(self, qm):
        # type: (Manager) -> None

        for cookie in qm.cookies:
            self._registry[cookie] = qm

    def unregister(self, sink):
        # type: (Manager) -> None
        with LOCK:
            for cookie in sink.cookies:
                try:
                    del self._registry[cookie]
                except KeyError:
                    LOGGER.warning('No Manager in registry with cookie: {}'.format(cookie))

    def get_by_cookie(self, cookie):
        return self._registry[cookie]


QUERY_MANAGER_STORE = QueryManagerStore()


class DispatcherThread(object):
    def __init__(self):
        self._stop_event = threading.Event()
        self._thread = threading.Thread(target=self._run, args=())

    def start(self):
        self._thread.setDaemon(True)
        self._thread.start()
        return self

    def _run(self):
        while not self._stop_event.is_set():
            message_header, message_byte_stream = RESPONSES_QUEUE.get()  # blocking
            msg_class = msg_id_to_msg_class.get(message_header.id)
            msg_tmp = msg_class().deserialize(message_byte_stream)

            try:
                context_id = msg_tmp.contextId
                procedure_id = msg_tmp.procedureId
            except AttributeError:
                context_id = 0
                procedure_id = 0
            cookie = (message_header.id, context_id, procedure_id)

            try:
                query_manager = QUERY_MANAGER_STORE.get_by_cookie(cookie)
            except KeyError:
                LOGGER.warning('No query_manager registered with cookie {}'.format(cookie))
                continue

            query_manager.digest(message_byte_stream)

    def stop(self):
        self._stop_event.set()
        self._thread.join(1.0)


@add_to__all__
class Query(object):
    def __init__(self, req_msg, resp_msg):
        # type: (RequestMessage, Union[ResponseMessage, None]) -> None
        self.req_msg = req_msg
        self.resp_msg = resp_msg
        self.resp_stream = None  # type: bytearray

        self.complete = False

    def handle_response(self, byte_stream):
        self.resp_stream = byte_stream
        self.resp_msg.deserialize(self.resp_stream)

        # rest of the logic must be implemented in subclasses
        self._handle_response()
        self._decide_if_complete()

    def _handle_response(self):
        raise NotImplementedError

    def _decide_if_complete(self):
        self.complete = True


@add_to__all__
@add_metaclass(ABCMeta)
class Manager(object):
    def __init__(self):
        self._cookies = []

    @abstractmethod
    def digest(self, byte_stream):
        pass

    @property
    def cookies(self):
        return self._cookies

    @abstractmethod
    def _set_cookies(self):
        pass

    def _register(self):
        self._set_cookies()
        QUERY_MANAGER_STORE.register(self)


@add_to__all__
class BasicQueryManager(Manager):
    def __init__(self, query, connection=None):
        super(BasicQueryManager, self).__init__()
        self.query = query
        self._register()
        self.connection = connection
        self._response_received = threading.Event()

    def _set_cookies(self):
        try:
            context_id = self.query.req_msg.contextId
            procedure_id = self.query.req_msg.procedureId
        except AttributeError:
            context_id = 0
            procedure_id = 0
        msg_id = self.query.resp_msg.id
        self._cookies.append((msg_id, context_id, procedure_id))

    def send_request(self):
        # type: () -> None
        message_sanity_check(self.query.req_msg.header)
        msg_stream = self.query.req_msg.serialize()

        with LOCK:
            self.connection.send(msg_stream)
            msg_name = msg_id_to_msg_name.get(self.query.req_msg.header.id)
            LOGGER.debug('--> {} {}'.format(msg_name, repr(msg_stream)))

    def send_request_and_wait_for_response(self, timeout=2):
        self.send_request()
        self._response_received.wait(timeout)

    def digest(self, byte_stream):
        self.query.handle_response(byte_stream)
        if self.query.complete:
            self._response_received.set()
            QUERY_MANAGER_STORE.unregister(self)


class RecvState(object):
    Start = 0
    Header = 1
    Payload = 2


class ReceiverThread(object):
    def __init__(self, connection):
        self.thread = threading.Thread(target=self._run)
        self._stop_event = threading.Event()
        self.connection = connection

    def start(self):
        self.thread.setDaemon(True)
        self.thread.start()

    def stop(self):
        self._stop_event.set()
        self.thread.join(1.0)

    def _run(self):  # noqa: C901
        message_header = None
        message_header_size = ctypes.sizeof(SMessageHeader)

        byte_stream = bytearray()

        state = RecvState.Header

        while not self._stop_event.is_set():

            chunk = self.connection.receive()  # blocking
            if chunk:
                byte_stream.extend(chunk)

            while byte_stream:
                if state == RecvState.Header and len(byte_stream) < message_header_size:
                    break
                if state == RecvState.Payload and len(byte_stream) < message_header.length:
                    break

                if state == RecvState.Header and len(byte_stream) >= message_header_size:
                    # we have the whole header
                    try:
                        message_header = SMessageHeader.from_buffer(
                            change_endianness(byte_stream[:message_header_size]))
                    except ValueError as e:
                        raise ByteStreamLengthError(str(e))

                    if not (message_header_size <= message_header.length < MESSAGE_MAX_LENGTH):
                        LOGGER.warning('Message header may be corrupted: id {} length {}'.format(
                            message_header.id, message_header.length)
                        )

                    # change state
                    state = RecvState.Payload

                if state == RecvState.Payload and len(byte_stream) >= message_header.length:
                    # we have the whole message
                    message_byte_stream = byte_stream[:message_header.length]

                    msg_name = msg_id_to_msg_name.get(message_header.id)
                    if message_header.id in TRACES_IDS:
                        LOGGER.debug('<-S {} sender={}'.format(msg_name, message_header.sender))
                    elif message_header.length > 150:
                        LOGGER.debug('<-H {} {}'.format(msg_name, repr(message_header)))
                    else:
                        LOGGER.debug('<-- {} {}'.format(msg_name, repr(message_byte_stream)))
                    # logger.debug('<-- {} {}'.format(msg_name, repr(message_byte_stream)))

                    RESPONSES_QUEUE.put((message_header, message_byte_stream))

                    # leave the remaining bytes for further processing as they belong to next message
                    byte_stream = byte_stream[message_header.length:]

                    # change state
                    state = RecvState.Header
